static void check_event_sample(bool vehicle_mode, ride_event_t event,
                               float x_g, float y_g, float z_g,
                               bool expected_active)
{
    ride_events_t state;
    ride_sample_t baseline = {0.0f, 0.0f, 0.0f, 100U};
    ride_sample_t sample = {x_g, y_g, z_g, 101U};

    ride_events_init(&state, vehicle_mode);
    ride_events_sample(&state, &baseline);
    ride_events_sample(&state, &sample);

    TEST_ASSERT_EQUAL_INT(expected_active, state.active[event]);
    if (expected_active)
    {
        TEST_ASSERT_EQUAL_UINT32(101U, state.last_event_ms[event]);
    }
    else
    {
        TEST_ASSERT_EQUAL_UINT32(0U, state.last_event_ms[event]);
    }
}

